"""Build an offline, self-contained numeric waveform viewer; no face imagery."""
import json,sys,html
from pathlib import Path
p=Path(sys.argv[1]);report=json.loads((p/'comparison.json').read_text());waves=json.loads((p/'waveforms.json').read_text());stream=json.loads((p/('stream-wide.json' if (p/'stream-wide.json').exists() else 'stream.json')).read_text())
data=json.dumps(dict(report=report,waves=waves,stream=stream)).replace('<',chr(92)+'u003c')
page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pulse Cathedral · Real video benchmark</title>
<style>*{box-sizing:border-box}body{margin:0;background:#101916;color:#e3eee7;font:16px system-ui;line-height:1.5}main{max-width:1100px;margin:40px auto;padding:0 24px}h1{font-size:32px;line-height:1.2}p{max-width:850px;color:#b7c8bf}small{color:#b7c8bf}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:10px;text-align:left;border-bottom:1px solid #33483d}.scroll{overflow:auto}.controls{position:sticky;top:0;background:#1c2c23;padding:16px;border-radius:12px;z-index:2;display:flex;gap:16px;align-items:center;flex-wrap:wrap}input{flex:1;min-width:160px;accent-color:#b4e6bc}select{background:#243c2e;color:white;padding:8px;border:1px solid #5f7968;border-radius:6px}canvas{width:100%;height:180px;display:block;background:#16221b;border-radius:8px;margin:8px 0 20px}h2{font-size:18px;margin:24px 0 4px}.flag{border-left:4px solid #dfb979;padding:12px 18px;background:#26271d}a{color:#b4e6bc}</style>
<main><small>PULSE CATHEDRAL / DEVELOPMENT BENCHMARK</small><h1>What the camera signal actually contains</h1><p>First 120 seconds of an official MPU-rPPG sample. All traces below are numeric signals; no face images are embedded. This is a diagnostic experiment, not held-out physiological validation.</p>
<p class="flag"><b>Not ready for IBI/HRV accuracy claims.</b> The sample lacks raw synchronization timestamps and independently reviewed beat labels. Its 60 fps container also shows a strong three-frame image-change cadence. Pairing is inferred from adjacent file IDs and identical frame/reference row counts.</p>
<div class="scroll"><table><thead><tr><th>Method</th><th>HR MAE vs device HR</th><th>Scored windows/readouts</th><th>Accepted readout fraction</th></tr></thead><tbody id="results"></tbody></table></div>
<p><small>Classical baselines use offline zero-phase filtering and overlapping 8-second windows. Production runs use streaming gates and their native readout cadence; rows are not a controlled latency comparison. Removing region agreement and widening the mask are diagnostic experiments, not released fixes.</small></p>
<div class="controls"><label for="start">Start <b id="at"></b></label><input id="start" type="range" min="0" max="110" value="40" step=".1"><label for="length">Window</label><select id="length"><option value="10">10 seconds</option><option value="20">20 seconds</option><option value="60">60 seconds</option></select></div>
<p><small>Each trace is centered and scaled independently within the selected window. Time is unchanged: no alignment fitting, time warping or beat-spacing regularization. Gaps in committed waveforms remain gaps.</small></p><div id="plots"></div>
<h2>Provenance and limits</h2><p><a href="https://doi.org/10.6084/m9.figshare.29377835">Official dataset</a> · <a href="https://www.nature.com/articles/s41597-026-07310-3">Dataset paper</a> · <a href="comparison.json">Full metrics JSON</a></p><ul id="limits"></ul><small id="revision"></small></main>
<script>const DATA=__DATA__;const fmt=x=>x==null?'Withheld':x.toFixed(2);const tbody=document.querySelector('#results');for(const [name,m] of Object.entries(DATA.report.results)){let tr=document.createElement('tr');for(const value of [name,fmt(m.maeBpm)+(m.maeBpm==null?'':' bpm'),m.windows,m.acceptedReadoutFraction==null?'Not gated':(100*m.acceptedReadoutFraction).toFixed(1)+'%']){let td=document.createElement('td');td.textContent=value;tr.append(td)}tbody.append(tr)}
for(const text of DATA.report.limitations){let li=document.createElement('li');li.textContent=text;document.querySelector('#limits').append(li)}document.querySelector('#revision').textContent='Pinned Toolbox revision: '+DATA.report.toolbox.commit;
const traces=[{name:'Contact PPG reference · raw',t:DATA.waves.referenceT,y:DATA.waves.referencePPG,color:'#ddd'}];for(const [name,y] of Object.entries(DATA.waves.signals))traces.push({name,t:DATA.waves.t.slice(0,y.length),y,color:'#b4e6bc'});for(const [name,r] of Object.entries(DATA.stream))traces.push({name:name+' · committed streaming waveform',t:r.waveform.map(p=>p.t),y:r.waveform.map(p=>p.value),color:'#dfb979'});
for(const tr of traces){let title=document.createElement('h2');title.textContent=tr.name;let c=document.createElement('canvas');c.setAttribute('aria-label',tr.name);document.querySelector('#plots').append(title,c);tr.canvas=c}
function draw(){let start=+document.querySelector('#start').value,len=+document.querySelector('#length').value;document.querySelector('#start').max=Math.max(0,DATA.waves.t.at(-1)-len);start=Math.min(start,+document.querySelector('#start').max);document.querySelector('#at').textContent=start.toFixed(1)+' s';for(const tr of traces){let c=tr.canvas,r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=180*d;let ctx=c.getContext('2d');ctx.scale(d,d);let w=r.width,h=180,pts=tr.t.map((t,i)=>[t,tr.y[i]]).filter(p=>p[0]>=start&&p[0]<=start+len&&Number.isFinite(p[1]));ctx.fillStyle='#a8bcb0';ctx.font='12px system-ui';if(!pts.length){ctx.fillText('No waveform here: capture reset or warmup.',20,90);continue}let mean=pts.reduce((s,p)=>s+p[1],0)/pts.length,sd=Math.sqrt(pts.reduce((s,p)=>s+(p[1]-mean)**2,0)/pts.length)||1;ctx.strokeStyle='#354c3e';ctx.beginPath();ctx.moveTo(36,90);ctx.lineTo(w-12,90);ctx.stroke();ctx.strokeStyle=tr.color;ctx.lineWidth=1.5;ctx.beginPath();let prev=null;for(const [t,y] of pts){let x=36+(t-start)/len*(w-48),py=90-(y-mean)/sd*24;if(prev===null||t-prev>.15)ctx.moveTo(x,py);else ctx.lineTo(x,py);prev=t}ctx.stroke();ctx.fillText(start.toFixed(1)+' s',36,170);ctx.fillText((start+len).toFixed(1)+' s',w-70,170);ctx.fillText('± SD',4,20)}}document.querySelector('#start').addEventListener('input',draw);document.querySelector('#length').addEventListener('change',draw);window.addEventListener('resize',draw);draw();</script></html>'''
if report.get('dataset','').startswith('Kaggle'):
 page=page.replace('First 120 seconds of an official MPU-rPPG sample.','120 seconds of Kaggle subject 1, starting at video time 20 seconds.')
 start=page.index('<p class="flag">');end=page.index('</p>',start)+4
 page=page[:start]+'<p class="flag"><b>Development test, not ECG validation.</b> Reference is 64 Hz Empatica wrist PPG. The visible start marker and recording duration support tags 2–3. End-marker discrepancy is about 0.34 s over seven minutes; no drift correction or waveform-fitted alignment is applied. Sparse IBI references retain their gaps.</p>'+page[end:]
 page=page.replace('https://doi.org/10.6084/m9.figshare.29377835','https://www.kaggle.com/datasets/ashfakyeafi/rppg-dataset/data').replace('Official dataset','Kaggle dataset')
 page=page.replace(' · <a href="https://www.nature.com/articles/s41597-026-07310-3">Dataset paper</a>','')
 page=page.replace('min="0" max="110" value="40"','min="20" max="130" value="60"')
(p/'report.html').write_text(page.replace('__DATA__',data));print(p/'report.html')
